-- 1174: Blog post - "A Full Room and a Kit Each: Our 25 July 2015 Hydroponics Class"
--
--       Seventh post for WSQ - Basic Urban Farming with Hydroponics (TGS-2025053916),
--       and the second-earliest by date (after 1172's 8 Mar 2014 first class).
--       The 25 Jul 2015 class at Toh Orchid Farm, taught by Geoffrey Chow.
--       Cross-links to five sibling posts.
--       Ships already published (status 1); linkedin_urn carries the manual-skip
--       sentinel (back-dated post - standing rule, see the blog-pipeline skill).
--       published_at pinned to 2015-07-25.
--
-- TRAINER NAME: the admin wrote "Geogrey Chow"; the slide in one photograph carries
-- the credit line "GChow 25/7/15", which confirms both the surname and the date but
-- not the given-name spelling. The copy uses the conventional "Geoffrey Chow" -
-- flag to the admin if his preferred spelling differs.
--
-- Claims about him are limited to what the photographs support: he taught this class,
-- and the cascade-NFT slide he presented carries his own credit line (i.e. it is his
-- own photograph of a system, not stock art). No biography or credentials asserted.
--
-- Every course figure was read off the LIVE course page on 2026-08-29: $350 before
-- GST, GST $31.50 (9%), nett $206.50 / $136.50, 1 day / 8 hrs at MEOD Farm, funding
-- valid 24 Mar 2025 - 23 Mar 2027, TSC AGR-FOP-2002-1.1.
--
-- VENUE: the 2015 class was at Toh Orchid Farm (past tense); MEOD Farm is named as
-- the CURRENT venue. Today's venue is not retro-fitted onto the 2015 photos.
--
-- CERTIFICATE: the photograph shows a "Certificate of Accomplishment" for a "Basic
-- Hydroponics Course" - the copy says exactly that, and contrasts it with today's
-- WSQ Certificate of Achievement + SkillsFuture OpenCert rather than implying the
-- 2015 class carried WSQ accreditation (it did not).
--
-- Photographs: 7 selected from a 19-shot album. 960px-native 2015 exports averaging
-- 67KB, already well under the <150KB compression target, so uploaded AS-IS -
-- re-encoding would only destroy quality for no saving. Total 472KB, all verified
-- HTTP 200. Under blog/hydroponics/2015-07-25-*.
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line - the content HTML is ONE line.
--  * Content is pure ASCII; excerpt uses a REAL em-dash via CHAR() (see 1161);
--    meta_description carries NO em-dash entity (see 1164).
--  * FAQ ships as native <details> accordions per the blog-pipeline rules.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links.
--  * SG-only guard via @mms_instance.
--  * hero_image_url is NOT set here - generated on prod post-deploy (farming theme).

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);


INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'A Full Room and a Kit Each: Our 25 July 2015 Hydroponics Class', 'hydroponics-class-2015-geoffrey-chow-toh-orchid-farm', CONCAT('Twenty-five people, a kit each, and a trainer who had actually built the systems he was teaching. Our 25 July 2015 hydroponics class at Toh Orchid Farm, taught by Geoffrey Chow ', CHAR(0xE2,0x80,0x94 USING utf8mb4), ' what a hands-on class looked like a decade before hydroponics became a national talking point.'), '<p>By the middle of 2015 our hydroponics classes had stopped being a curiosity and started filling up. The class on <strong>25 July 2015</strong> at <strong>Toh Orchid Farm</strong> was one of the biggest we had run: a long table down each side of the room, a grow kit in front of every seat, and <strong>Geoffrey Chow</strong> teaching.</p> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2015-07-25-class-group-photo.jpg" alt="The large 25 July 2015 hydroponics class posing together for a group photograph at Toh Orchid Farm" /> <figcaption>The 25 July 2015 class at Toh Orchid Farm. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>This is a look back at what a hands-on hydroponics class looked like in Singapore a decade ago &mdash; before the "30 by 30" goal was announced, before vertical farms were a sector, and well before anyone was calling this a national capability.</p> <h2>Taught by someone who had built the systems</h2> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2015-07-25-geoffrey-chow-teaching.jpg" alt="Geoffrey Chow standing beside a projected slide showing a cascade nutrient film technique system, teaching the seated class" /> <figcaption>Geoffrey Chow presenting a cascade nutrient film technique system &mdash; his own photograph, from his own build. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>Look at what is on the screen: a <strong>cascade nutrient film technique</strong> system, photographed in a real greenhouse rather than lifted from a textbook. The slide carries his own credit line in the corner.</p> <p>That is the difference a practitioner makes. A trainer working from a manual can tell you a cascade NFT system stacks channels so solution falls from one level to the next. A trainer who has built one tells you which joints leak, how much fall you actually need between tiers, and what happens on the day the pump stops. The questions people asked in that room were answerable because the person at the front had already made the mistakes.</p> <h2>A kit each &mdash; not a demonstration</h2> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2015-07-25-class-at-their-kits.jpg" alt="Participants seated along both sides of a long table, each with a black hydroponic grow tub and lid in front of them, turning to face the camera" /> <figcaption>Every seat has a tub, a lid and a set of net pots. Nobody watches from the back. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>Count the tubs. That is the rule the course has never broken: <strong>one working system per learner</strong>, assembled by that learner, in the room. It is the single most expensive decision in running a class like this and the one that most determines whether anyone actually grows anything afterwards.</p> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2015-07-25-assembling-grow-tubs.jpg" alt="Participants standing around a table handling a black grow tub and its lid, with net pots, nutrient bottles and growing media laid out in front of them" /> <figcaption>The practical session: fitting lids, seating net pots, and finding out how the parts actually go together. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>The practical session is where the theory gets tested against your hands. The lid has to sit so the net pots hold the medium at the right depth &mdash; close enough to the solution that it wicks upward, not so deep that the medium is submerged and the roots suffocate. You can describe that in a sentence. You only really learn it by holding the pot and deciding.</p> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2015-07-25-nutrients-seeds-media.jpg" alt="A supply table laid out with nutrient concentrate bottles, pH solutions, seed packets, net pots, clay pebbles and other growing media" /> <figcaption>The supply table: nutrient concentrates, pH solutions, seed packets and growing media. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>And this is the answer to "what do I actually need to buy" &mdash; a question every class asks. Nutrient A and B concentrates, pH up and down, a growing medium, net pots, seed. The list is short and unglamorous, which is usually a relief to hear.</p> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2015-07-25-classroom-session.jpg" alt="Wide view of the full classroom during the session, participants seated at tables with their kits while the trainer teaches at the front" /> <figcaption>The room mid-session: theory at the front, kits waiting on every table. Photo: Tertiary Infotech Academy.</figcaption> </figure> <h2>Everyone leaves with something that works</h2> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2015-07-25-certificate-presentation.jpg" alt="A smiling participant receiving her Certificate of Accomplishment for the Basic Hydroponics Course from the trainer at the end of the class" /> <figcaption>End of the day: a certificate, and a system you assembled yourself. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>The certificate mattered less than the tub, honestly &mdash; but both went home. In 2015 that was a Certificate of Accomplishment from the course provider. The course today carries WSQ accreditation, a formal assessment, a Skills Framework mapping and an OpenCert from SkillsFuture Singapore, none of which existed for this class.</p> <p>What has not changed is the shape of the day: understand the principle, build the system, take it home, keep it alive.</p> <h2>What a decade changed &mdash; and what it did not</h2> <p>Comparing 2015 with a class we run now:</p> <ul> <li><strong>The context changed completely.</strong> In 2015 hydroponics was a hobby with an interesting future. Singapore has since set a national food-production target, commercial vertical farms have opened, and the skill has funding attached to it.</li> <li><strong>The accreditation arrived.</strong> WSQ funding, SkillsFuture Credit, PSEA and UTAP now bring a $350 course down to $206.50 or $136.50 nett. In 2015 you simply paid the fee.</li> <li><strong>The equipment got cheaper and better.</strong> Meters that were specialist purchases are now commodity items, which matters because measurement is the whole discipline.</li> <li><strong>The physics did not move at all.</strong> Roots still need water, nutrients and oxygen. pH still decides whether a plant can absorb what is in the tank. A lid still keeps algae out of a reservoir. Everything taught in that room in 2015 is still true.</li> </ul> <h2>The course today</h2> <p><a href="https://www.tertiarycourses.com.sg/wsq-basic-urban-farming-with-hydroponics.html">WSQ - Basic Urban Farming with Hydroponics</a> (course code TGS-2025053916) is a <strong>1-day, 8-hour</strong> class at Beginner level with a 1-hour assessment, held at <strong>MEOD Farm, 13 Neo Tiew Harvest Lane</strong>. It maps to the SkillsFuture Skills Framework TSC <strong>Urban Farming Implementation and Management Control (AGR-FOP-2002-1.1)</strong>, with two learning outcomes:</p> <ol> <li>Perform farming activities and equipment operations according to standard operating procedures</li> <li>Execute farming operations work in accordance with regulations, WSH practices and housekeeping rules</li> </ol> <p>The day covers hydroponic system types (deep water culture, nutrient film technique, wick, ebb and flow, drip), growing media, plant nutrition and nutrient solutions, pH and EC monitoring, indoor farming conditions, Singapore''s urban farming regulations, good agriculture practices and workplace safety &mdash; plus hands-on practice with a hydroponics kit and a guided tour of a commercial hydroponics farm.</p> <h3>What it costs</h3> <p>The full fee is <strong>$350</strong> before GST. With WSQ funding:</p> <table> <tr><th>Who you are</th><th>Nett fee</th><th>Funding</th></tr> <tr><td>Singapore Citizen / PR, aged 21 and above</td><td><strong>$206.50</strong></td><td>50% course-fee funding</td></tr> <tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td><strong>$136.50</strong></td><td>70% course-fee funding</td></tr> </table> <p>GST of $31.50 (9%) applies to the full course fee. Funding is valid <strong>from 24 March 2025 to 23 March 2027</strong>. Eligible Singapore Citizens can apply <strong>SkillsFuture Credit</strong> and <strong>PSEA</strong> against the nett fee, NTUC members may claim <strong>UTAP</strong>, and employers can tap <strong>SFEC</strong> with <strong>Absentee Payroll</strong> support. Completion &mdash; at least 75% attendance plus a pass in the assessment &mdash; earns a Certificate of Achievement from Tertiary Infotech Academy and an <strong>OpenCert (Statement of Achievement) from SkillsFuture Singapore</strong>.</p> <p><a href="https://www.tertiarycourses.com.sg/wsq-basic-urban-farming-with-hydroponics.html"><strong>Check the next class date and funding eligibility &rarr;</strong></a></p> <h2>Frequently asked questions</h2> <div class="mmd-faq"> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Do I still get to build and keep a system?</summary> <div class="mmd-faq-a"><p>Hands-on practice with a hydroponics kit is part of the day, exactly as it was in 2015 &mdash; you assemble a working system rather than watch a demonstration. Check the current course page or ask us about what you take home, since that detail can change between runs.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">What is cascade nutrient film technique?</summary> <div class="mmd-faq-a"><p>NFT with the channels stacked so solution falls from one tier to the next before returning to the reservoir. It multiplies growing area per square metre of floor, which is why it appeals in land-scarce settings. The course covers NFT alongside deep water culture, wick, ebb and flow, and drip systems.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">What do I actually need to buy to start at home?</summary> <div class="mmd-faq-a"><p>A tub with a lid, net pots, a growing medium such as clay pebbles or rockwool, nutrient A and B concentrates, pH adjusters and seed. The two things worth spending real attention on are a TDS/EC meter and a pH meter &mdash; without them you are growing blind.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Is the certificate the same as in 2015?</summary> <div class="mmd-faq-a"><p>No, it is considerably more. The 2015 class earned a Certificate of Accomplishment from the provider. Today, on at least 75% attendance and a pass in the assessment, you receive a Certificate of Achievement from Tertiary Infotech Academy and an OpenCert (Statement of Achievement) from SkillsFuture Singapore certifying the Skills Framework competency.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Where is the class held now?</summary> <div class="mmd-faq-a"><p>At MEOD Farm, 13 Neo Tiew Harvest Lane, Singapore 719838. The 2015 class was at Toh Orchid Farm; the venue has changed over the years, but teaching on a working farm has not.</p></div> </details> </div> <h2>Where to go next</h2> <p>A decade on, the room still fills and the kits still go home. The reason is unchanged: a hydroponic system is simple enough to learn in a day and interesting enough to keep adjusting for years.</p> <ol> <li>Start with leafy greens and herbs, and get through one complete crop cycle before changing anything.</li> <li>Join the next <a href="https://www.tertiarycourses.com.sg/wsq-basic-urban-farming-with-hydroponics.html"><strong>WSQ - Basic Urban Farming with Hydroponics</strong></a> class &mdash; from <strong>$136.50 nett</strong> for eligible Singapore Citizens aged 40 and above.</li> <li>Buy the two meters early and keep a log. It is the difference between growing and guessing.</li> </ol> <p>More from this course: <a href="https://www.tertiarycourses.com.sg/blog/hydroponics-first-class-2014-dr-mallick">our very first class in 2014</a>, <a href="https://www.tertiarycourses.com.sg/blog/urban-farming-with-hydroponics-guide">how hydroponics works</a>, <a href="https://www.tertiarycourses.com.sg/blog/hydroponics-jar-of-water-windowsill-singapore-july-2025">hydroponics in a jam jar</a>, <a href="https://www.tertiarycourses.com.sg/blog/hydroponics-kit-practical-build-singapore-december-2025">building a deep water culture kit</a>, and <a href="https://www.tertiarycourses.com.sg/blog/hydroponics-commercial-farm-visit-singapore-february-2020">inside a working hydroponic farm</a>.</p>', 'Tertiary Infotech Academy', 1, '2015-07-25', 'TGS-2025053916', 'TGS-2025053916', 'Our 2015 Hydroponics Class at Toh Orchid Farm | WSQ Course Singapore', 'Twenty-five learners, a grow kit each, and a trainer who had built the systems he taught. Our 25 July 2015 hydroponics class at Toh Orchid Farm with Geoffrey Chow, and how the course has changed since. WSQ funded from $136.50 nett.', 'geoffrey chow hydroponics, toh orchid farm, hydroponics class singapore 2015, cascade nutrient film technique, hydroponics course singapore, urban farming singapore, wsq hydroponics, hydroponics kit, skillsfuture urban farming', 'manual-skip', NOW(), NOW() FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'hydroponics-class-2015-geoffrey-chow-toh-orchid-farm') x);

-- Tags (core Magento tag vocabulary; status 1 = approved)
INSERT INTO `tag` (`name`, `status`) SELECT 'Urban Farming', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Urban Farming') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Hydroponics', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Hydroponics') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Sustainability', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Sustainability') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'hydroponics-class-2015-geoffrey-chow-toh-orchid-farm');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('Urban Farming', 'Hydroponics', 'Sustainability', 'WSQ');

